import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.yMGLHqpH.js";const g=JSON.parse('{"title":"Gentoo / Calculate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/gentoo.md","filePath":"guide/gentoo.md"}'),n={name:"guide/gentoo.md"};function o(r,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="gentoo-calculate" tabindex="-1">Gentoo / Calculate <a class="header-anchor" href="#gentoo-calculate" aria-label="Permalink to &quot;Gentoo / Calculate&quot;">​</a></h1><p>Gentoo users can install <code>net-proxy/dae</code> from the <a href="https://github.com/gentoo-zh/overlay/tree/master/net-proxy/dae" target="_blank" rel="noreferrer">gentoo-zh overlay</a>. This package is maintained by the Gentoo community and uses Portage. The APT/RPM version table on this site describes a separate repository.</p><p>Run the following commands as root. The keyword example applies to amd64 systems.</p><h2 id="_1-add-and-synchronize-the-overlay" tabindex="-1">1. Add and synchronize the overlay <a class="header-anchor" href="#_1-add-and-synchronize-the-overlay" aria-label="Permalink to &quot;1. Add and synchronize the overlay&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emerge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-eselect/eselect-repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev-vcs/git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">eselect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gentoo-zh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/gentoo-zh/overlay.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emaint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gentoo-zh</span></span></code></pre></div><p>If gentoo-zh is already configured, run only the synchronization command. Mirror selection and manual configuration are covered in the <a href="https://gentoozh.org/overlay/" target="_blank" rel="noreferrer">gentoo-zh overlay guide</a>.</p><h2 id="_2-accept-the-testing-keyword" tabindex="-1">2. Accept the testing keyword <a class="header-anchor" href="#_2-accept-the-testing-keyword" aria-label="Permalink to &quot;2. Accept the testing keyword&quot;">​</a></h2><p>On a stable amd64 system, add this entry to <code>package.accept_keywords</code>. If <code>/etc/portage/package.accept_keywords</code> is a directory, use a file inside it, such as <code>/etc/portage/package.accept_keywords/dae</code>. If it is a file, add the entry there.</p><div class="language-text vp-adaptive-theme"><button title="Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net-proxy/dae::gentoo-zh ~amd64</span></span></code></pre></div><p>Systems already using <code>~amd64</code> globally can skip this step. For other architectures, check the selected ebuild&#39;s <code>KEYWORDS</code> before choosing a keyword.</p><h2 id="_3-install-dae" tabindex="-1">3. Install dae <a class="header-anchor" href="#_3-install-dae" aria-label="Permalink to &quot;3. Install dae&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">emerge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> net-proxy/dae::gentoo-zh</span></span></code></pre></div><p>Review Portage&#39;s kernel configuration checks. The ebuild installs OpenRC and systemd service files and an example configuration at <code>/usr/share/dae/config.dae.example</code>. Configure dae before starting its service; see the <a href="https://github.com/daeuniverse/dae#readme" target="_blank" rel="noreferrer">dae documentation</a>.</p><h2 id="optional-mirrors-and-binary-packages" tabindex="-1">Optional: mirrors and binary packages <a class="header-anchor" href="#optional-mirrors-and-binary-packages" aria-label="Permalink to &quot;Optional: mirrors and binary packages&quot;">​</a></h2><p>Follow the <a href="https://gentoozh.org/overlay/" target="_blank" rel="noreferrer">gentoo-zh overlay guide</a> for Distfiles mirrors, binhost channels and signature verification. Check the <a href="https://distfiles.gentoozh.org/packages" target="_blank" rel="noreferrer">binary package list</a> for availability; Portage can build from source when no suitable binary package exists.</p>`,15)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
